/** The words of the reader's language. */
export const mots = () => MOTS[lang()];
/**
 * The address of the house's studio page, behind its name in the foot's signature (ADR-0026), by the reader's language:
 * written here and nowhere else. `depuis` says where the reader comes from, for that page's display only. The same
 * page in both languages for now; the English one will be https://anotherframework.dev/en/studio.html?depuis=runward.
 * It is an address, not a word: it stays out of MOTS, whose English values are held free of French.
 */
const STUDIO = { fr: "https://anotherframework.dev/studio.html?depuis=runward", en: "https://anotherframework.dev/studio.html?depuis=runward" };
export const studioUrl = () => STUDIO[lang()];
/**
 * An address of the public site, runward.dev, by the reader's language (ADR-0028): French at /<page>, English at
 * /en/<page>; no page, its home. The pages this origin served until 2026-11-11 are there, under the same names
 * (src/http/moved.js holds the same origin for the server's redirections). Written here and nowhere else in the shell.
 */
const SITE = "https://runward.dev";
export const siteUrl = (page = "") => (lang() === "en" ? `${SITE}/en${page ? `/${page}` : ""}` : `${SITE}/${page}`);

// The values the service writes in French, said in the reader's language (the API is unchanged): a fleet's title when
// it is the store's default, the product's French name (src/adapters/store/tables.js); a passkey's provider when the
// service names it in French (src/domain/identity.js#AAGUIDS); the word that joins a browser and its system in a
// device's label (« Chrome sur macOS », src/domain/identity.js#deviceFromUserAgent).
/** A fleet's title: the operator's own, as written; the store's default, in the reader's language. */
export const titreFlotte = (t) => (t === MOTS.fr.brand ? mots().brand : t);
/** A passkey's provider or a device's label, as the service writes it, in the reader's language; none stays none. */
export function appareil(d) {
  if (!d) return d;
  const k = Object.keys(MOTS.fr.providers).find((x) => MOTS.fr.providers[x] === d);
  return k ? mots().providers[k] : String(d).replace(MOTS.fr.common.deviceJoin, mots().common.deviceJoin);
}
